static inline DWORD ROL32(DWORD x, int n) { return (x << n) | (x >> (32 - n)); }
static inline DWORD ROR32(DWORD x, int n) { return (x >> n) | (x << (32 - n)); }

static inline DWORD U8TO32(const BYTE* p) {
    return ((DWORD)p[0]) | ((DWORD)p[1] << 8) | ((DWORD)p[2] << 16) | ((DWORD)p[3] << 24);
}
static inline void U32TO8(BYTE* p, DWORD v) {
    p[0] = (BYTE)v; p[1] = (BYTE)(v >> 8); p[2] = (BYTE)(v >> 16); p[3] = (BYTE)(v >> 24);
}

#define QR(a,b,c,d) \
    a += b; d ^= a; d = ROL32(d, 16); \
    c += d; b ^= c; b = ROL32(b, 12); \
    a += b; d ^= a; d = ROL32(d,  8); \
    c += d; b ^= c; b = ROL32(b,  7);

static void ChaChaBlock(const BYTE key[32], const BYTE nonce[12], DWORD counter, BYTE out[64]) {
    DWORD x[16];
    const BYTE* sigma = (const BYTE*)"expand 32-byte k";
    x[0]  = U8TO32(sigma + 0);
    x[1]  = U8TO32(sigma + 4);
    x[2]  = U8TO32(sigma + 8);
    x[3]  = U8TO32(sigma + 12);
    x[4]  = U8TO32(key + 0);  x[5]  = U8TO32(key + 4);
    x[6]  = U8TO32(key + 8);  x[7]  = U8TO32(key + 12);
    x[8]  = U8TO32(key + 16); x[9]  = U8TO32(key + 20);
    x[10] = U8TO32(key + 24); x[11] = U8TO32(key + 28);
    x[12] = counter;
    x[13] = U8TO32(nonce + 0);
    x[14] = U8TO32(nonce + 4);
    x[15] = U8TO32(nonce + 8);

    DWORD w[16];
    MemCpy(w, x, sizeof(w));
    for (int i = 0; i < 10; i++) {
        QR(w[0], w[4], w[ 8], w[12]); QR(w[1], w[5], w[ 9], w[13]);
        QR(w[2], w[6], w[10], w[14]); QR(w[3], w[7], w[11], w[15]);
        QR(w[0], w[5], w[10], w[15]); QR(w[1], w[6], w[11], w[12]);
        QR(w[2], w[7], w[ 8], w[13]); QR(w[3], w[4], w[ 9], w[14]);
    }
    for (int i = 0; i < 16; i++) w[i] += x[i];
    for (int i = 0; i < 16; i++) U32TO8(out + 4 * i, w[i]);
}

static void ChaChaCrypt(const BYTE key[32], const BYTE nonce[12], BYTE* data, SIZE_T len, DWORD counter_start) {
    BYTE block[64];
    DWORD counter = counter_start;
    SIZE_T i = 0;
    while (i < len) {
        ChaChaBlock(key, nonce, counter++, block);
        SIZE_T chunk = len - i < 64 ? len - i : 64;
        for (SIZE_T j = 0; j < chunk; j++) data[i + j] ^= block[j];
        i += chunk;
    }
}

